"""The 50 eval cases, defined BEFORE the prototype exists (labels = what the generator plants).

C01-C20 are Ugo's cases from evals/eval_set_v0.csv (rows already in the CSV).
C21-C50 are new (their CSV rows are written by data/make_data.py).

Fields: id, hotel, ticket, total reviews, top3 (planted, in count order) or None,
handover reason or None, q3 (reviews in the current quarter), r (planted share of Q3 reviews for the top 3),
lang (foreign-language share), flags (traps), segment, note.
Handover reasons: few_reviews | non_english_reviews | non_english_ticket | multi_hotel | not_rating_drop
"""

DEFAULT_R = (0.26, 0.17, 0.10)


def C(id, hotel, ticket, total, top3=None, handover=None, q3=None, r=DEFAULT_R, lang=None, flags=(),
      segment="en · 3-star · urban", note=""):
    return dict(id=id, hotel=hotel, ticket=ticket, total=total, top3=top3, handover=handover, q3=q3, r=r,
                lang=lang or {}, flags=tuple(flags), segment=segment, note=note)


